using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

namespace CSER
{
    /// Radio voice-over with subtitles. Lines live in Resources/VO/narration.json; each has a matching
    /// Resources/VO/{file}.wav generated by Tools/generate_vo.ps1 (Windows speech synthesis).
    public class Narrator : MonoBehaviour
    {
        public static Narrator I { get; private set; }

        [Serializable] public class Line { public string key; public string speaker; public string text; public string file; }
        [Serializable] class LineList { public Line[] lines; }

        readonly Dictionary<string, List<Line>> groups = new Dictionary<string, List<Line>>();
        readonly Queue<Line> queue = new Queue<Line>();
        AudioSource voice;
        Coroutine running;

        public bool Speaking => running != null;
        public event Action GroupFinished;

        // clear the static when the scene unloads, so later scenes never call into a destroyed instance
        void OnDestroy() { if (I == this) I = null; }

        void Awake()
        {
            I = this;
            voice = gameObject.AddComponent<AudioSource>();
            voice.playOnAwake = false;
            voice.spatialBlend = 0;
            voice.volume = 1f;
            var json = Resources.Load<TextAsset>("VO/narration");
            if (!json) return;
            foreach (var l in JsonUtility.FromJson<LineList>(json.text).lines)
            {
                if (!groups.TryGetValue(l.key, out var list)) groups[l.key] = list = new List<Line>();
                list.Add(l);
            }
        }

        public bool Has(string key) => groups.ContainsKey(key);

        /// Interrupts whatever is playing and speaks the group for this key.
        public void Play(string key)
        {
            if (!groups.TryGetValue(key, out var list)) return;
            queue.Clear();
            foreach (var l in list) queue.Enqueue(l);
            if (running != null) StopCoroutine(running);
            voice.Stop();
            running = StartCoroutine(Run());
        }

        public void Stop()
        {
            queue.Clear();
            if (running != null) StopCoroutine(running);
            running = null;
            voice.Stop();
            GameUI.I?.Subtitle(null, null, 0);
        }

        IEnumerator Run()
        {
            yield return new WaitForSeconds(0.25f);
            while (queue.Count > 0)
            {
                var l = queue.Dequeue();
                var clip = Resources.Load<AudioClip>("VO/" + l.file);
                float dur = clip ? clip.length : Mathf.Clamp(l.text.Length * 0.06f, 2f, 9f);
                if (clip) voice.PlayOneShot(clip);
                GameUI.I?.Subtitle(l.speaker, l.text, dur + 0.6f);
                yield return new WaitForSeconds(dur + 0.35f);
            }
            running = null;
            GroupFinished?.Invoke();
        }
    }
}
